def dump_stack(stack):
    idx = 1
    for num in stack:
        print(f"{' '.join(f'{c:02x}' for c in num.to_bytes(2, 'little'))}", end="\n" if idx % 8 == 0 else " ")
        idx += 1

def dump_instructions(instructions):
    idx = 1
    for b in instructions:
        print(f"{f'{b:02x}'}", end="\n" if idx % 16 == 0 else " ")
        idx += 1

def core_dump():
    global count
    global a
    global b
    print(f"count: {count}")
    print("Dumping Stacks")
    print("\nStack A:")
    dump_stack(a)
    print("\n\nStack B:")
    dump_stack(b)

while ip < len(data):
    opcode = data[ip]
    count += 1
    # Stack A Operations
    if opcode == 0x10:
        ip += 1
        a.append(a[-1])
    elif opcode == 0x11:
        ip += 1
        a.pop()
    elif opcode == 0x12:
        ip += 1
        a.append(a.pop() + a.pop())
    elif opcode == 0x13:
        ip += 1
        a.append(-a.pop() + a.pop())
    elif opcode == 0x14:
        ip += 1
        tmp0 = a.pop()
        tmp1 = a.pop()
        a.append(tmp0)
        a.append(tmp1)
    
    # Stack Transfer
    elif opcode == 0x20:
        ip += 1
        b.append(a.pop())
    elif opcode == 0x21:
        ip += 1
        a.append(b.pop())
    
    # Control Flow
    elif opcode == 0x30:
        ip = a.pop()
    elif opcode == 0x31:
        ip += 1
        dest = a.pop()
        if a.pop() == 0:
            ip = dest
    elif opcode == 0x32:
        ip += 1
        dest = a.pop()
        if a.pop() != 0:
            ip = dest
    elif opcode == 0x33:
        ip += 1
        dest = a.pop()
        if a.pop() < 0:
            ip = dest
    elif opcode == 0x34:
        ip += 1
        dest = a.pop()
        if a.pop() > 0:
            ip = dest
    
    #IO
    elif opcode == 0xc0:
        ip += 1
        if len(input_buff) == 0:
            input_buff = list(input("User Input:"))[::-1]
            print("")
        a.append(ord(input_buff.pop()))
    elif opcode == 0xc1:
        ip += 1
        print(chr(a.pop()), end="")
    # Data input
    elif opcode == 0x80:
        a.append(data[ip+1])
        ip += 2
    elif opcode == 0x81:
        a.append(data[ip+1] + data[ip+2]*0x100)
        ip += 3
    
    # Break
    elif opcode == 0xaa:
        core_dump()
        ip += 1
    
    else:
        print(f"\n\nInvalid Instruction at {hex(ip)} : {hex(opcode)}")
        core_dump()
        exit()
    